const body = $json.body ?? $json;
const value = body.entry?.[0]?.changes?.[0]?.value ?? body;
const message = value.messages?.[0] ?? body.message;
const contact = value.contacts?.[0] ?? body.contact ?? {};

// Ignore delivery/status callbacks: the dashboard lists inbound customer messages only.
if (!message) return [];

const text = message.text?.body
  ?? message.button?.text
  ?? message.interactive?.button_reply?.title
  ?? message.interactive?.list_reply?.title
  ?? body.text
  ?? '';

return [{
  json: {
    wa_id: contact.wa_id ?? message.from ?? body.wa_id,
    profileName: contact.profile?.name ?? body.profileName ?? 'Customer',
    message_id: message.id ?? body.message_id ?? `${message.from}-${message.timestamp}`,
    text,
    messageType: message.type ?? body.messageType ?? 'text',
    receivedAt: message.timestamp
      ? new Date(Number(message.timestamp) * 1000).toISOString()
      : (body.receivedAt ?? new Date().toISOString()),
  },
}];
